#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

typedef struct {
    int to;
    int weight;
    int edge_id;
    int next;
} Edge;

#define MAXE 10005
#define MAXR 40005

int head[MAXE];
Edge edges[MAXR * 2];
int edge_cnt = 0;

void add_edge(int u, int v, int w, int id) {
    edges[edge_cnt] = (Edge){v, w, id, head[u]};
    head[u] = edge_cnt++;
    edges[edge_cnt] = (Edge){u, w, id, head[v]};
    head[v] = edge_cnt++;
}

int depth[MAXE];
int parent_node[MAXE];
int parent_edge_weight[MAXE];
int parent_edge_id[MAXE];
bool visited[MAXE];
long long cycle_len[MAXE];

void dfs_cycles(int u, int p, int p_edge_id, int d) {
    visited[u] = true;
    depth[u] = d;

    for (int e = head[u]; e != -1; e = edges[e].next) {
        if (edges[e].edge_id == p_edge_id) continue;
        int v = edges[e].to;
        int w = edges[e].weight;

        if (visited[v]) {
            if (depth[v] < depth[u]) {
                // Encontrou um ciclo simples
                long long clen = w;
                int curr = u;
                while (curr != v) {
                    clen += parent_edge_weight[curr];
                    curr = parent_node[curr];
                }
                curr = u;
                while (curr != v) {
                    cycle_len[curr] = clen;
                    curr = parent_node[curr];
                }
                cycle_len[v] = clen;
            }
        } else {
            parent_node[v] = u;
            parent_edge_weight[v] = w;
            parent_edge_id[v] = edges[e].edge_id;
            dfs_cycles(v, u, edges[e].edge_id, d + 1);
        }
    }
}

// Min-Heap para o Dijkstra
typedef struct {
    int u;
    long long dist;
} HeapNode;

HeapNode heap[MAXR * 4];
int heap_size = 0;

void push(int u, long long d) {
    int i = heap_size++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i] = (HeapNode){u, d};
}

HeapNode pop() {
    HeapNode top = heap[0];
    HeapNode last = heap[--heap_size];
    if (heap_size > 0) {
        int i = 0;
        while (i * 2 + 1 < heap_size) {
            int left = i * 2 + 1;
            int right = i * 2 + 2;
            int best = left;
            if (right < heap_size && heap[right].dist < heap[left].dist) {
                best = right;
            }
            if (last.dist <= heap[best].dist) break;
            heap[i] = heap[best];
            i = best;
        }
        heap[i] = last;
    }
    return top;
}

long long dist[MAXE];

int main() {
    int E, R;
    if (scanf("%d %d", &E, &R) != 2) return 0;

    for (int i = 1; i <= E; i++) {
        head[i] = -1;
        cycle_len[i] = 0;
        visited[i] = false;
    }

    for (int i = 0; i < R; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(u, v, w, i);
    }

    // Identificar ciclos
    for (int i = 1; i <= E; i++) {
        if (!visited[i]) {
            dfs_cycles(i, 0, -1, 1);
        }
    }

    int K;
    if (scanf("%d", &K) != 1) return 0;

    while (K--) {
        int X;
        long long T;
        scanf("%d %lld", &X, &T);

        for (int i = 1; i <= E; i++) {
            dist[i] = INF;
        }

        heap_size = 0;
        dist[X] = 0;
        push(X, 0);

        long long ans = INF;

        while (heap_size > 0) {
            HeapNode cur = pop();
            int u = cur.u;
            long long d = cur.dist;

            if (d > dist[u]) continue;

            if (cycle_len[u] >= T) {
                long long candidate = 2 * d + cycle_len[u];
                if (candidate < ans) {
                    ans = candidate;
                }
            }

            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                int w = edges[e].weight;
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    push(v, dist[v]);
                }
            }
        }

        if (ans >= INF) {
            printf("-1\n");
        } else {
            printf("%lld\n", ans);
        }
    }

    return 0;
}
